const cfg = $('Config').first().json;
const ticket = $('New Ticket').first().json.body ?? $('New Ticket').first().json;
let parsed = {};
try { parsed = JSON.parse($json?.choices?.[0]?.message?.content || '{}'); } catch {}
const confidence = Number(parsed.confidence || 0);
const risky = /refund|billing|legal|password|security|delete|contract/i.test(`${ticket.subject || ''} ${ticket.body || ticket.message || ''}`);
