const suggested = String(parsed.suggested_reply || 'No draft reply was generated.');
return [{ json: { ticket_id: ticket.id || ticket.ticket_id || 'unknown', category: parsed.category || 'unclassified', priority: parsed.priority || 'normal', confidence, needs_review: needsReview, summary, suggested_reply: suggested, content: `🧑‍⚖️ **Ticket review required**
ID: ${ticket.id || ticket.ticket_id || 'unknown'}
